<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { allPages, api, message } from '../api'
import { can, inScope, session } from '../session'
import { dateTime, spaceTypes, type Department, type OpeningHour, type Space } from '../types'
import { useList } from '../useList'
import Icon from '../components/Icon.vue'
import Modal from '../components/Modal.vue'
import PageState from '../components/PageState.vue'
import Pagination from '../components/Pagination.vue'
const {data,loading,error,load}=useList<Space>();const page=ref(0);const type=ref('');const query=ref('');const departments=ref<Department[]>([])
const open=ref(false);const editing=ref<Space|null>(null);const detail=ref<Space|null>(null);const parents=ref<Space[]>([]);const busy=ref(false);const formError=ref('');const copied=ref(false)
const form=ref({type:'ROOM',parentId:'',code:'',name:'',departmentId:'',capacity:40,features:'',openingHours:[] as OpeningHour[],active:true})
const parentType=computed(()=>({BUILDING:'CAMPUS',ROOM:'BUILDING',SEAT:'ROOM'}[form.value.type]))
const availableTypes=computed(()=>session.user?.roles.includes('ADMIN')?spaceTypes:{ROOM:'教室',SEAT:'座位'})
function deptName(id:string|null){return departments.value.find(d=>d.id===id)?.name??'全校公共'}
function reload(){return load(`/resources?page=${page.value}&size=20&type=${type.value}&q=${encodeURIComponent(query.value)}`)}
let timer:ReturnType<typeof setTimeout>
watch(query,()=>{clearTimeout(timer);timer=setTimeout(()=>{page.value=0;void reload()},300)})
watch(type,()=>{page.value=0;void reload()});watch(page,reload)
onMounted(async()=>{void reload();try{departments.value=await api<Department[]>('/departments')}catch(e){formError.value=message(e)}})
async function loadParents(){if(!parentType.value){parents.value=[];return}parents.value=await allPages<Space>(`/resources?type=${parentType.value}`)}
async function create(){editing.value=null;formError.value='';form.value={type:'ROOM',parentId:'',code:'',name:'',departmentId:session.user?.departmentId??'',capacity:40,features:'',openingHours:[],active:true};open.value=true;try{await loadParents()}catch(e){formError.value=message(e)}}
async function edit(space:Space){editing.value=space;formError.value='';form.value={type:space.type,parentId:space.parentId??'',code:space.code,name:space.name,departmentId:space.departmentId??'',capacity:space.capacity,features:space.features.join('，'),openingHours:space.openingHours.map(h=>({...h,start:h.start.slice(0,5),end:h.end.slice(0,5)})),active:space.active};open.value=true}
async function changeType(){form.value.parentId='';form.value.capacity=form.value.type==='SEAT'?1:form.value.type==='ROOM'?40:0;form.value.openingHours=[];try{await loadParents()}catch(e){formError.value=message(e)}}
function parentChanged(){if(form.value.type==='SEAT')form.value.departmentId=parents.value.find(p=>p.id===form.value.parentId)?.departmentId??''}
async function save(){busy.value=true;formError.value='';try{const body={name:form.value.name,capacity:form.value.capacity,features:form.value.features.split(/[,，]/).map(s=>s.trim()).filter(Boolean),openingHours:form.value.openingHours,active:form.value.active};if(editing.value)await api(`/resources/${editing.value.id}`,'PUT',{...body,expectedVersion:editing.value.version});else await api('/resources','POST',{...body,type:form.value.type,parentId:form.value.parentId||null,code:form.value.code,departmentId:['ROOM','SEAT'].includes(form.value.type)?form.value.departmentId:null});open.value=false;await reload()}catch(e){formError.value=message(e)}finally{busy.value=false}}
async function copyId(id:string){try{await navigator.clipboard.writeText(id);copied.value=true}catch{copied.value=false}}
</script>
<template><div class="page-heading"><div><div class="eyebrow">CAMPUS / SPACES</div><h1>空间资源</h1><p>从校区到座位，一份清晰、统一的校园空间目录。</p></div><button v-if="can('spaces.write')" class="button" @click="create"><Icon name="plus" :size="17"/>新增空间</button></div><div class="info-strip"><Icon name="shield" :size="18"/><p>这里维护基础信息与开放规则。预约占用、审批和维修限制由各业务模块管理。</p></div><section class="panel"><div class="toolbar"><div class="tab-filters" aria-label="资源类型"><button :class="{selected:!type}" @click="type=''">全部</button><button v-for="(label,key) in spaceTypes" :key="key" :class="{selected:type===key}" @click="type=String(key)">{{label}}</button></div><label class="search-input"><Icon name="search" :size="17"/><input v-model="query" aria-label="搜索空间名称或编号" placeholder="搜索名称或编号" maxlength="100"></label></div><PageState :loading="loading" :error="error" :empty="!data.items.length" empty-text="暂无匹配的空间" @retry="reload"><div class="table-scroll"><table><thead><tr><th>空间名称 / 编号</th><th>类型</th><th>归属院系</th><th>容量</th><th>基础状态</th><th>更新时间</th><th class="align-right">操作</th></tr></thead><tbody><tr v-for="space in data.items" :key="space.id"><td><div class="entity-cell"><span class="entity-icon"><Icon :name="space.type==='SEAT'?'chair':'space'" :size="18"/></span><div><strong>{{space.name}}</strong><small>{{space.code}}</small></div></div></td><td>{{spaceTypes[space.type]}}</td><td>{{deptName(space.departmentId)}}</td><td>{{space.capacity||'—'}}</td><td><span class="badge" :class="{neutral:!space.effectiveActive}"><i/>{{space.effectiveActive?'启用':space.active?'上级停用':'已停用'}}</span></td><td class="muted nowrap">{{dateTime(space.updatedAt)}}</td><td class="align-right nowrap"><button class="text-link" @click="detail=space;copied=false">详情</button><button v-if="can('spaces.write')&&inScope(space.departmentId)" class="text-link" @click="edit(space)">编辑</button></td></tr></tbody></table></div><Pagination :page="page" :total="data.total" :size="20" @change="page=$event"/></PageState></section>
<Modal v-if="open" :title="editing?'编辑空间':'新增空间'" @close="open=false"><form class="form-body" @submit.prevent="save"><div class="form-grid"><label>类型<select v-model="form.type" :disabled="!!editing" @change="changeType"><option v-for="(label,key) in availableTypes" :key="key" :value="key">{{label}}</option></select></label><label>空间编号<input v-model="form.code" required maxlength="48" pattern="[A-Za-z0-9._-]+" :disabled="!!editing" placeholder="如 EIE-A101"><small>使用字母、数字、点、下划线或短横线</small></label></div><label>空间名称<input v-model="form.name" required maxlength="100" placeholder="如 信息楼 A101 教室"></label><label v-if="parentType&&!editing">上级{{spaceTypes[parentType]}}<select v-model="form.parentId" required @change="parentChanged"><option value="" disabled>请选择上级空间</option><option v-for="parent in parents.filter(p=>p.effectiveActive&&(form.type!=='SEAT'||inScope(p.departmentId)))" :key="parent.id" :value="parent.id">{{parent.name}} · {{parent.code}}</option></select><small v-if="!parents.length">请先建立上级空间后再创建。</small></label><div class="form-grid"><label v-if="['ROOM','SEAT'].includes(form.type)">归属院系<select v-model="form.departmentId" required :disabled="!!editing||form.type==='SEAT'||!session.user?.roles.includes('ADMIN')"><option value="" disabled>请选择院系</option><option v-for="dep in departments" :key="dep.id" :value="dep.id">{{dep.name}}</option></select></label><label>容量<input v-model.number="form.capacity" type="number" required :min="['ROOM','SEAT'].includes(form.type)?1:0" :max="form.type==='SEAT'?1:10000"></label></div><label>空间属性<input v-model="form.features" maxlength="800" placeholder="投影仪，自习，电源插座"><small>用逗号分隔，最多 20 个，每个不超过 40 个字符。</small></label><div v-if="form.type==='ROOM'" class="hours-editor"><div class="section-heading"><label>每周开放时段</label><button type="button" class="text-link" @click="form.openingHours.push({day:1,start:'08:00',end:'22:00'})">+ 添加时段</button></div><p v-if="!form.openingHours.length" class="muted small-text">尚未配置开放时段，业务模块应视为未开放。</p><div v-for="(hour,index) in form.openingHours" :key="index" class="hours-row"><select v-model.number="hour.day" :aria-label="`时段 ${index+1} 星期`"><option v-for="(day,i) in ['一','二','三','四','五','六','日']" :key="day" :value="i+1">星期{{day}}</option></select><input v-model="hour.start" type="time" required :aria-label="`时段 ${index+1} 开始`"><span>至</span><input v-model="hour.end" type="time" required :aria-label="`时段 ${index+1} 结束`"><button type="button" class="icon-button" aria-label="移除时段" @click="form.openingHours.splice(index,1)"><Icon name="close" :size="16"/></button></div></div><label class="checkbox-label"><input v-model="form.active" type="checkbox">启用此空间</label><p class="muted small-text">停用保留历史记录；上级停用时，下级空间同步不可用于新业务。</p><p v-if="formError" role="alert" class="form-error">{{formError}}</p><div class="form-actions"><button type="button" class="button secondary" @click="open=false">取消</button><button class="button" :disabled="busy">{{busy?'正在保存…':'保存空间'}}</button></div></form></Modal>
<Modal v-if="detail" :title="detail.name" @close="detail=null"><div class="form-body"><div class="detail-code"><span class="badge">{{spaceTypes[detail.type]}}</span><strong>{{detail.code}}</strong></div><dl class="detail-list"><dt>资源编号</dt><dd class="mono break">{{detail.id}} <button class="text-link" @click="copyId(detail.id)">{{copied?'已复制':'复制'}}</button></dd><dt>院系</dt><dd>{{deptName(detail.departmentId)}}</dd><dt>上级编号</dt><dd class="mono break">{{detail.parentId||'无'}}</dd><dt>容量</dt><dd>{{detail.capacity}}</dd><dt>基础状态</dt><dd>{{detail.effectiveActive?'启用':detail.active?'上级停用':'已停用'}}</dd><dt>版本</dt><dd>{{detail.version}}</dd><dt>属性</dt><dd>{{detail.features.join(' · ')||'未设置'}}</dd><template v-if="detail.type==='ROOM'"><dt>开放时段</dt><dd><p v-for="(hour,i) in detail.openingHours" :key="i">星期{{['一','二','三','四','五','六','日'][hour.day-1]}} {{hour.start.slice(0,5)}}—{{hour.end.slice(0,5)}}</p><span v-if="!detail.openingHours.length">未配置</span></dd></template></dl><div class="form-actions"><button class="button secondary" @click="detail=null">关闭</button></div></div></Modal></template>
